insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-226","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Acid-catalysed hydrolysis of methyl acetate in a large excess of water is treated as","options":["pseudo first order in the ester","second order in water","zero order in the ester","third order overall under all conditions"],"answer_index":0,"explanation":"[H$_2$O] is essentially constant, so the observed rate is first order in ester only.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-227","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a reaction that proceeds by several elementary steps, the overall order","options":["need not equal the molecularity of any one step, and is found only by experiment","is always equal to the number of steps","must equal the molecularity of the last step","is undefined if a catalyst is present"],"answer_index":0,"explanation":"Order is a property of the observed rate law. Molecularity belongs to individual steps.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-228","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Termolecular elementary steps are rare because","options":["a simultaneous collision of three molecules is statistically improbable","three molecules can never share electrons","the collision theory forbids $n = 3$ exactly","Faraday's laws prohibit them"],"answer_index":0,"explanation":"Two-body collisions are common; a third body arriving in the same instant is unlikely, so $n = 3$ steps are scarce.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-229","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate constant reported as L$^2$ mol$^{-2}$ s$^{-1}$ indicates that the reaction is","options":["third order overall","first order overall","zero order overall","fractional order of ½"],"answer_index":0,"explanation":"Units of $k$ are (conc.)$^{1-n}$ (time)$^{-1}$. L$^2$ mol$^{-2}$ s$^{-1}$ corresponds to $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-230","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Mechanism: fast equilibrium A + B ⇌ I, followed by slow I → P. The observed order in A and the molecularity of the slow step are","options":["first order in A, and unimolecular","second order in A, and bimolecular","zero order in A, and termolecular","first order in A, and bimolecular"],"answer_index":0,"explanation":"The RDS is unimolecular in I. Substituting [I] = $K[\\mathrm{A}][\\mathrm{B}]$ makes the rate first order in A (and in B).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-231","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated first-order rate law is commonly written","options":["$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$[\\mathrm{A}]^2 = kt$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]$ yields a linear plot of $\\ln[\\mathrm{A}]$ versus $t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-232","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a zero-order decay the concentration falls linearly according to","options":["$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] = 1/[\\mathrm{A}]_0 + kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 e^{+kt}$"],"answer_index":0,"explanation":"Rate $= k$ (constant), so [A] drops at a constant slope $-k$ until the reactant is exhausted.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-233","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated law for a simple second-order reaction 2A → products is","options":["$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$[\\mathrm{A}]_0 - [\\mathrm{A}] = k\\ln t$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]^2$ produces the reciprocal-concentration relation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-234","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hallmark of first-order kinetics is that the half-life","options":["does not depend on the starting concentration","is proportional to $[\\mathrm{A}]_0$","is inversely proportional to $[\\mathrm{A}]_0$","grows as $[\\mathrm{A}]_0^2$"],"answer_index":0,"explanation":"$t_{1/2} = \\ln 2 / k$ contains no $[\\mathrm{A}]_0$. Each successive half-life has the same duration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-235","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Zero-order half-life grows when the initial concentration is raised because","options":["$t_{1/2} = [\\mathrm{A}]_0 / (2k)$","$t_{1/2} = \\ln 2 / k$","$t_{1/2} = 1 / (k[\\mathrm{A}]_0)$","$t_{1/2}$ is independent of $[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"A constant rate needs longer to consume half of a larger starting amount.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-236","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For the second-order process 2A → products, half-life and initial concentration are related by","options":["$t_{1/2} = 1 / (k[\\mathrm{A}]_0)$","$t_{1/2} = \\ln 2 / k$","$t_{1/2} = [\\mathrm{A}]_0 / (2k)$","$t_{1/2} = k[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"Set [A] = [A]$_0$/2 in $1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$ to obtain $t_{1/2} = 1/(k[\\mathrm{A}]_0)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-237","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"After $n$ successive half-lives of a first-order reaction the fraction of reactant left is","options":["$(1/2)^n$","$n/2$","$1/n$","$2^n$"],"answer_index":0,"explanation":"Each half-life halves what remains, so the leftover fraction is $2^{-n}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-238","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A straight line is obtained when $\\ln[\\mathrm{A}]$ is plotted against time for a reaction that is","options":["first order in A","zero order in A","second order in A","third order in A"],"answer_index":0,"explanation":"The first-order integrated law is $\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-239","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A plot of [A] versus time is linear with a negative slope when the reaction is","options":["zero order in A","first order in A","second order in A","fractional order ½"],"answer_index":0,"explanation":"[A] = [A]$_0 - kt$ is the equation of a straight line of slope $-k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-240","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A graph of $1/[\\mathrm{A}]$ versus time is a straight line when the decay of A is","options":["second order","first order","zero order","a pure nuclear explosion"],"answer_index":0,"explanation":"The second-order integrated law is linear in $1/[\\mathrm{A}]$, with slope $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-241","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a first-order reaction has consumed 75% of the reactant, the number of half-lives that have elapsed is","options":["two","one","three","four"],"answer_index":0,"explanation":"75% consumed means 25% remains, which is $(1/2)^2$ of the start, i.e. two half-lives.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-242","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Radioactive disintegration is treated kinetically as","options":["first order in the amount of nuclide","zero order in every case","second order in the daughter nuclide","third order in the neutron number"],"answer_index":0,"explanation":"Each nucleus decays independently, so the rate is proportional to the number remaining: first-order kinetics.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-243","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The half-life of a zero-order reaction with rate constant $k$ equals","options":["$[\\mathrm{A}]_0/(2k)$","$\\ln 2 / k$","$1/(k[\\mathrm{A}]_0)$","$2k/[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"Set $[\\mathrm{A}] = [\\mathrm{A}]_0/2$ in $[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$ to obtain $t_{1/2} = [\\mathrm{A}]_0/(2k)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-244","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order process never quite reaches 100% conversion because","options":["the rate keeps falling as [A] falls, so a finite time cannot exhaust the last traces","the integrated law forbids $t > t_{1/2}$","zero-order kinetics take over near the end","$k$ becomes infinite as [A] approaches zero"],"answer_index":0,"explanation":"[A] = [A]$_0 e^{-kt}$ approaches zero only as $t \\to \\infty$. In practice the reactant becomes undetectable, but the law has no finite finish time.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-245","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order gas reaction has $k = 1.386 \\times 10^{-2}\\ \\mathrm{min^{-1}}$. Its half-life is","options":["50 min","0.693 min","72 min","100 min"],"answer_index":0,"explanation":"$t_{1/2} = 0.693/k = 0.693/(1.386 \\times 10^{-2}) = 50\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-246","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If 60% of a first-order reactant remains after 20 min, the leftover fraction after a further 20 min is nearest","options":["0.36","0.60","0.16","0.48"],"answer_index":0,"explanation":"First order: the same time interval multiplies [A] by the same factor 0.60, so $0.60 \\times 0.60 = 0.36$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-247","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"How long does a first-order reaction of half-life 15 min take to reach 75% completion?","options":["30 min","15 min","45 min","7.5 min"],"answer_index":0,"explanation":"75% completion is two half-lives, so $2 \\times 15 = 30\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-248","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"From a measured first-order half-life of 46.2 min one obtains $k$ equal to","options":["$1.50 \\times 10^{-2}\\ \\mathrm{min^{-1}}$","$46.2\\ \\mathrm{min^{-1}}$","$0.693\\ \\mathrm{min^{-1}}$","$3.00 \\times 10^{-2}\\ \\mathrm{min^{-1}}$"],"answer_index":0,"explanation":"$k = 0.693/t_{1/2} = 0.693/46.2 = 1.50 \\times 10^{-2}\\ \\mathrm{min^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-249","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A zero-order reaction with $k = 2.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ min^{-1}}$ and $[\\mathrm{A}]_0 = 0.20\\ \\mathrm{M}$ is complete after","options":["100 min","50 min","200 min","0.10 min"],"answer_index":0,"explanation":"Completion means $[\\mathrm{A}] = 0$, so $t = [\\mathrm{A}]_0/k = 0.20/(2.0 \\times 10^{-3}) = 100\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-250","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Starting from a first-order sample, the number of half-lives needed to leave only one-eighth of the reactant is","options":["3","2","4","8"],"answer_index":0,"explanation":"$(1/2)^n = 1/8$ gives $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
